SELECT CASE WHEN budget >= 3761000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, dept_name, ROUND(AVG(budget), 2) AS avg_budget, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Finance' THEN 1 END), 0), 2) AS budget_per_finance, STDDEV_SAMP(budget) AS budget_stddev, COUNT(DISTINCT dept_name) AS distinct_dept_names, COUNT(*) AS num_rows FROM departments GROUP BY CASE WHEN budget >= 3761000 THEN 'LARGE' ELSE 'SMALL' END, dept_name HAVING ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Finance' THEN 1 END), 0), 2) >= 0 ORDER BY distinct_dept_names DESC
